css:
/* Outer card */
.u-container {
  background: #ffffff;
  border-radius: 24px;
  padding: 18px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
}

/* Inner soft surface */
.u-inner {
  width: 250px;
  background: #fafafa;
  border-radius: 18px;
  padding: 24px 14px;
  text-align: center;
}

/* Icon */
.u-icon {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  background: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 18px;
  color: #000000;
}

/* Title */
.u-title {
  font-size: 18px;
  font-weight: 600;
  color: #000000;
  margin-bottom: 10px;
}

/* Description */
.u-text {
  font-size: 14px;
  color: #7a7a7a;
  line-height: 1.5;
  margin-bottom: 24px;
}

/* Button */
.u-button {
  width: 100%;
  height: 48px;
  background: #000000;
  color: #ffffff;
  border: none;
  border-radius: 12px;
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition:
    transform 0.12s ease,
    opacity 0.12s ease;
}

.u-button:active {
  transform: scale(0.97);
  opacity: 0.9;
}

/* Input */
.u-input {
  display: none;
}
